  "recommendation": "Purple Account",
  "reason": "It has no Rho fee for foreign ATM withdrawals, rebates foreign ATM operator fees up to $30 per month, and has a $1,000 daily ATM withdrawal limit.",
  "comparison": {
    "Purple Account": {
      "foreign_atm_fee": "$0.00 per withdrawal",
      "operator_fee_rebate": "Up to $30 per month",
