    },
    "Green Fee-Free Account": {
      "foreign_atm_fee": "$0.00 per withdrawal",
      "operator_fee_rebate": "No rebate stated",
      "daily_atm_limit": "$500",
      "monthly_fee": "$22.50, waived with a $150 minimum daily balance"
    },
    "Light Blue Account": {
      "foreign_atm_fee": "First 2 withdrawals per month free; $4.00 each thereafter"
    }
  },
  "important_note": "ATM operators may still charge fees. With Purple, eligible operator fees are rebated up to the $30 monthly cap. Choose to be charged in the local currency and decline dynamic currency conversion when offered.",
